import { code } from '../../code.ts';
import type { IosValues } from '../values.ts';

// The path of the file in plugins/ios.
export const path = (v: IosValues) => `${v.id}/src/${v.product}.mm`;

export default (v: IosValues) => code`
// clang-format off
// Generated by plugins/tools/generate.ts from plugins/plugins/${v.id}/plugin.json; do not edit.
#import <${v.product}/${v.product}.h>

#include "${v.header}"

NSErrorDomain const ${v.className}ErrorDomain = @"${v.errorDomain}";

@implementation ${v.className}

+ (BOOL)registerPluginWithError:(NSError **)error {
    char message[512] = {};
    const mln_plugin_status status = ${v.register}(&mln_plugin_register_v1, message, sizeof(message));
    if (status == MLN_PLUGIN_STATUS_OK || status == MLN_PLUGIN_STATUS_ALREADY_REGISTERED) {
        return YES;
    }
    if (error) {
        NSString *description = message[0] ? [NSString stringWithUTF8String:message]
                                            : @"MapLibre rejected the ${v.displayName} plugin";
        *error = [NSError errorWithDomain:${v.className}ErrorDomain
                                     code:status
                                 userInfo:@{NSLocalizedDescriptionKey: description ?: @""}];
    }
    return NO;
}

@end
`;
